// RentMethodsSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/digitenant/reports/rent/methods/list/RentMethodsSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import RentMethodsActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const RentMethodsSchema = {
  entity: 'rental_rent_methods',
  label: 'Payment Methods',
  description: '',
  apiBase: apiRoutes.rentmethods?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: RentMethodsActions,

  groupBy: 'payment_method',
  groupLabel: 'Method',
  sortBy: 'collected desc',

  fields: [
    { key: 'payments', label: 'Payments', from: 'rent_payments' },
    { key: 'collected', label: 'Rent Collected', from: 'rent_payments.amount', type: 'money' },
    { key: 'avg_payment', label: 'Average Payment', calc: 'collected / payments', type: 'money' },
    { key: 'share', label: 'Share of Collections', calc: 'share(collected)' },
  ],

  remarks: [
    { if: 'payments == 0', tone: 'neutral', title: 'Unused', say: 'Nothing was received by {label} in this period.' },
    { if: 'true', tone: 'neutral', title: 'Method', say: '{label}: {payments} payments totalling {collected}, averaging {avg_payment}.' },
  ],

  headline: '{label} is the most used: {payments} payments, {collected} collected, {share}% of all rent.',
};
